# W. Raymond Wood et Thomas D. Thiessen (éd.), Early Fur Trade on the Northern Plains: Canadian Traders among the Mandan and
# Hidatsa Indians, 1738-1818 (1985), PDF du Drive de l'auteur (dossier FUR_TRADE_USA). Corpus « Recherches », préfixe WT85 :
# les Canadiens résidents (« residenters ») des villages mandans et hidatsas, d'après l'introduction des éditeurs.
from commun import Corpus
WT = "Wood, W. Raymond et Thomas D. Thiessen (éd.) (1985), Early Fur Trade on the Northern Plains: Canadian Traders among the Mandan and Hidatsa Indians, 1738-1818, Norman, University of Oklahoma Press"
C = Corpus('Recherches', 'WT85', WT)
F = C.F
J = 'René Jusseaume'
F('01', "Village awatixa (site Sakakawea) : Ménard, premier Blanc établi chez les Hidatsas (v. 1778)", 'personnage', '1778~/1804', -101.388, 47.326, 'a', ['Ménard'],
  "Le premier Euro-Américain connu à s'établir à demeure dans les villages mandans et hidatsas est un Canadien nommé Ménard, dont le prénom s'est perdu (François ou Pierre selon des éditeurs plus tardifs). Six témoins le disent arrivé entre 1778 et 1783 ; il vit dans le village aujourd'hui appelé site Sakakawea, avec une femme indienne « belle et gracieuse », et David Thompson le juge « en tout point comme un indigène ». Onze sources contemporaines (D'Église, Truteau, Collot, Thompson, Larocque, McKenzie, Tabeau, Clark, Henry…) puisent chez lui leur savoir sur le haut Missouri : il connaît la Yellowstone et les Rocheuses, et a visité plusieurs fois les Crows avec les Hidatsas. Il est tué en revenant de l'Assiniboine, au grand regret du maître de Brandon House.",
  '43-46', "Position au site Sakakawea, sur la Knife (Knife River Indian Villages).")
F('02', "Les « residenters » canadiens des villages de la Knife (années 1790-1810)", 'etablissement', '1790~/1818', -101.39, 47.33, 'a', ['Ménard', J, 'Cardin', 'Jean-Baptiste Lafrance', 'Toussaint Charbonneau', 'François La Grave', 'Joseph Garreau', 'Chayé', 'Hugh Heney'],
  "Wood et Thiessen dressent la liste des résidents libres des villages mandans et hidatsas cités dans les papiers des compagnies : Cardin, La France, Toussaint Charbonneau, La Grave, « Chayé », Ménard, Joseph Garreau, René Jusseaume, ainsi que McCracken, Colter, Heney, Morgan, Holmes et Taylor. Plusieurs sont des déserteurs de la Compagnie du Nord-Ouest ou de Prairie du Chien : John Macdonell traite de « canaille » La Grave, Garreau et Chayé. Ils vivent de la revente de chevaux, de robes et de loups aux postes de l'Assiniboine.",
  '43, 50')
F('03', "Fort Espérance (Qu'Appelle) : première mention de Jusseaume et Cardin (13 avril 1794)", 'commerce', '1794-04-13', -101.67, 50.45, 'a', [J, 'Cardin', 'John Macdonell'],
  "La plus ancienne mention de René Jusseaume est l'entrée du journal de John Macdonell du 13 avril 1794 : lui et Cardin arrivent au fort Espérance avec un parti de la Compagnie du Nord-Ouest revenant du Missouri. Thompson dit qu'il vit dans les villages depuis 1789 ou 1790 ; Alexander Henry, en 1806, « depuis plus de quinze ans ».",
  '46 et n. 98', "Position approximative du fort Espérance, sur la Qu'Appelle près de l'actuelle Rocanville (Saskatchewan).")
F('04', "Poste de Jusseaume (« fort Makay ») entre les villages mandans et hidatsas (1794-1797)", 'poste', '1794-10-27/1797-05', -101.36, 47.30, 'h', [J, 'John Evans'],
  "Parti de la rivière la Souris le 17 octobre 1794, Jusseaume conduit une expédition de la Compagnie du Nord-Ouest qui élève, peu après son arrivée au Missouri le 27 octobre, « un petit fort et une cabane » sur la rive entre les villages mandans et hidatsas : le seul bâtiment construit par les traiteurs canadiens. En septembre 1796, l'explorateur John Evans s'en empare au nom de l'Espagne et le rebaptise fort Makay ; Jusseaume tente de le tuer.",
  '28, 46-49', "Position hypothétique sur la rive du Missouri près de l'embouchure de la Knife.")
F('05', "Villages mandans : David Thompson guidé par Jusseaume (hiver 1797-1798)", 'exploration', '1797-12/1798-01-22', -101.33, 47.28, 'a', [J, 'David Thompson', 'Joseph Boisseau', 'Alexis Vivier', 'Pierre Gilbert', 'François Perrault', 'Toussaint Vaudril', 'Louis-Jean-Baptiste Houle', 'Jean-Baptiste Minie'],
  "Jusseaume sert de guide et d'interprète à l'expédition de David Thompson aux villages mandans, avec Joseph Boisseau (domestique de Thompson), Hugh McCracken, Alexis Vivier, Pierre Gilbert, François Perrault, Toussaint Vaudril, Louis-Jean-Baptiste Houle et Jean-Baptiste Minie. Le 9 janvier 1798, Thompson reçoit de Jusseaume des peaux de loup et 48 robes de bison.",
  '57, 59, 97 et n. 8')
F('06', "Rivière Grand : Jusseaume blessé par les Arikaras (1807)", 'evenement', '1807-09', -100.47, 45.55, 'a', [J, 'Shahaka', 'Nathaniel Pryor', 'Pierre Chouteau'],
  "En 1807, l'expédition de Nathaniel Pryor et de Pierre Chouteau, chargée de ramener chez lui le chef mandan Shahaka (Big White), revenu de Washington, est repoussée à coups de fusil par les Arikaras près de la rivière Grand et doit rentrer à Saint-Louis. René Jusseaume, l'interprète de Big White, est blessé.",
  '31', "Position aux villages arikaras de l'embouchure de la Grand (Dakota du Sud).")
F('07', "Fort des Trembles (Poplar Fort), au-dessus du Portage la Prairie : les traiteurs Bruce et Boyer attaqués (1780 ou 1781)", 'evenement', '1780/1781', -98.120, 49.975, 'a', ['Bruce', 'Boyer', 'John Macdonell'],
  "Selon le manuscrit « The Red River » de John Macdonell, le fort des Trembles se dressait à trois lieues au-dessus du Portage la Prairie. En 1780 ou 1781, des Indiens tentent d'y piller les traiteurs Bruce et Boyer ; dans la mêlée, deux Français et sept Indiens sont tués sur place. Craignant d'être exterminés, les traiteurs se rembarquent pour aller hiverner aux Fourches ; la petite vérole, qui emporte alors les trois quarts des Indiens, fait avorter selon Macdonell le projet de couper la route à tous les Blancs de l'intérieur.", '82', "Emplacement approximatif, à trois lieues en amont de Portage la Prairie.")
F('08', "Portage la Prairie : William McKay contre Réaume et « Dejadon pour LaViolette » (hiver 1794-1795)", 'commerce', '1794/1795', -98.290, 49.970, 'a', ['William McKay', 'Réaume', 'Dejadon', 'LaViolette', 'John Macdonell'],
  "Macdonell rappelle que par ce portage d'environ douze milles on portait, sous les commandants français, les marchandises du fort Dauphin vers le lac Manitoba puis la rivière Dauphine. À cet endroit, William McKay hiverne en 1794-1795 pour la Compagnie du Nord-Ouest face à M. Réaume, à Dejadon (agissant pour LaViolette) et à Linklater de la Compagnie de la Baie d'Hudson, mieux pourvus que lui en marchandises, et fait pourtant de bons retours.", '82')
F('09', "Fort La Reine : « Old Pinneshon », soldat déserteur passé des Mandanes au service des traiteurs français (v. 1744-1753)", 'personnage', '1744~/1763~', -98.300, 49.975, 'h', ['Pinneshon', 'Peter Pond'],
  "Peter Pond rapporte qu'un ancien soldat français du pays des Illinois, déserteur, remonta le Missouri, vécut de longues années chez les Indiens et trouva chez les Mandanes des traiteurs du « fort Lorain » (fort La Reine) qui l'emmenèrent au poste, où la compagnie le prit à son service jusqu'à la cession du pays aux Anglais. Les éditeurs y voient peut-être Pennesha Gegare, traiteur français chez les Sauks et les Renards du Wisconsin en 1753 (aussi écrit Pennensha, Penechon ou « Mons. Pinnisance ») ; l'allusion viserait alors la décennie 1744-1753.", '24', "Identification proposée par les éditeurs ; voir aussi JI-pinnisance-portage-wi.")
F('10', "Pine Fort (fort des Épinettes), sur l'Assiniboine : poste de la traite mandane (1785-1794, réoccupé en 1807)", 'poste', '1785/1810~', -99.350, 49.750, 'a', ['François-Antoine Larocque', 'Charles McKenzie', 'John Macdonell'],
  "Fondé en 1785 par la Compagnie du Nord-Ouest sur la rive nord de l'Assiniboine, près de l'ancien site du fort La Reine et à dix-huit milles en aval de la Souris, le Pine Fort (fort des Épinettes, des Pins ou des Trembles) est le principal poste de la traite avec les Mandanes jusqu'à son abandon en 1794, la Compagnie de la Baie d'Hudson s'étant établie à côté ; les engagés y prenaient des peaux à crédit pour aller traiter aux villages du Missouri, à dix ou douze jours de marche. Le site est réoccupé en 1807 : Larocque y passe l'hiver suivant avant d'en partir le 3 juin, laissant le poste à Charles McKenzie.", '82-85, 203', "Emplacement approximatif.")
F('11', "Le jeune Lamothe, mis au ban par la Compagnie du Nord-Ouest pour la mort de James King (1806-1807)", 'personnage', '1806/1807', -99.350, 49.750, 'a', ['Lamothe', 'James King', 'François-Antoine Larocque', 'John Macdonell', 'Archibald Norman McLeod'],
  "Selon le récit de Larocque, malgré la fusion de 1804 la Compagnie du Nord-Ouest n'a pas pardonné au jeune Lamothe d'avoir tué en légitime défense, au département du fort des Prairies (Saskatchewan), le traiteur James King. Sous l'influence d'A. N. McLeod, John Macdonell promet de lui rendre la vie impossible pour le chasser du pays : sans commandement ni emploi, Lamothe est envoyé hiverner avec Larocque, qui trouve en lui un excellent compagnon. Au printemps, on le laisse au portage de la Montagne, sur la route de Kaministiquia, dernière mortification avant son renvoi vers Montréal.", '201-204', "Point placé au Pine Fort, où Larocque hiverne avec lui.")
F('12', "Saint-Hyacinthe : Larocque, né à L'Assomption, finit ses jours à l'Hôtel-Dieu (1855-1869)", 'personnage', '1784-08-19/1897', -72.955, 45.630, 'c', ['François-Antoine Larocque', 'Marie-Catherine-Émilie Cotte'],
  "Né le 19 août 1784 à L'Assomption, envoyé aux États-Unis apprendre l'anglais après la mort de son père (1792), commis de la XY puis de la Compagnie du Nord-Ouest, François-Antoine Larocque quitte l'Ouest en 1806. Capitaine des Chasseurs canadiens en 1812, prisonnier six mois à Cincinnati, il épouse en 1818 Marie-Catherine-Émilie Cotte et compte parmi les fondateurs de la Banque de Montréal (1819). Retiré des affaires en 1841, il entre en 1855 à l'Hôtel-Dieu de Saint-Hyacinthe, y meurt le 1er mai 1869 et est inhumé dans la crypte de l'église ; ses restes sont transférés en 1897 au cimetière des Sœurs grises, où une pierre porte encore « Antoine Larocque, 1869 ».", '129-130')
F('13', "Pointe-Fortune : John Macdonell, ancien bourgeois de la rivière Rouge, et Magdeleine Poitras (1814-1853)", 'famille', '1814/1853', -74.385, 45.560, 'c', ['John Macdonell', 'Magdeline Poitras', 'André Poitras'],
  "Auteur du manuscrit « The Red River », John Macdonell prend dans l'Ouest pour épouse à la façon du pays Magdeleine Poitras, fille d'André Poitras, traiteur de la Qu'Appelle, et d'une Indienne. Rentré en 1812, capitaine au Corps des voyageurs canadiens fait prisonnier à Saint-Régis, il vit dès 1814 à Pointe-Fortune, sur l'Outaouais, où il tient un magasin, fait courir des bateaux vers Montréal et siège comme juge. Il meurt le 17 avril 1850 à quatre-vingt-deux ans et est inhumé à Saint-André d'Argenteuil ; un mariage posthume célébré en 1853 légitime leur union et leurs huit enfants.", '77-78')
fiches = C.fiches
